const chat = $('Loop Chats').item.json || {};
const inst = $('Trigger').first().json.instance_name || '';
const remoteJid = chat.remote_jid || '';

const existingItem = $('Get Existing').item.json || {};
const prevTranscript = existingItem.transcript || '';

const all = $input.all().map((i) => i.json);
const toIso = (ts) => (ts ? new Date(ts * 1000).toISOString() : null);

if (all.length === 0) {
  return [{ json: {
    instance_name: inst,
    remote_jid: remoteJid,
    contact_name: chat.push_name || null,
    phone: remoteJid ? remoteJid.replace('@s.whatsapp.net', '') : null,
    transcript: prevTranscript,
    first_message_at: null,
    last_message_at: null,
    checkpoint: null,
  } }];
}

const lastTs = all[all.length - 1].ts;
const textRows = all.filter((r) => r.body);
let transcript = prevTranscript;
if (textRows.length) {
  const newText = textRows.map((r) => (r.from_me ? 'Eu' : 'Contato') + ': ' + r.body).join('\n');
  transcript = prevTranscript ? prevTranscript + '\n' + newText : newText;
}

return [{ json: {
  instance_name: inst,
  remote_jid: remoteJid,
  contact_name: chat.push_name || null,
  phone: remoteJid ? remoteJid.replace('@s.whatsapp.net', '') : null,
  transcript,
  first_message_at: null,
  last_message_at: toIso(lastTs),
  checkpoint: toIso(lastTs),
} }];
